"""Ensure that all annotations are in the image and start at pixel 1 at a minimum

    Args:
        bbox (list) : list of [x_min, y_min, x_max, y_max]
        img_shape (tup) : shape of image in the form: (y, x, channels)

    Returns:
        bbox (list) : list of cleaned [x_min, y_min, x_max, y_max]
    """
def check_bbox_in_image(bbox: Any, img_shape: Any) -> object {
    for i in range(len(bbox)) {
        if (bbox[i] <= 1.0) {
            bbox[i] = 1.0;
        }
    }
    if (bbox[2] >= img_shape[1]) {
        bbox[2] = img_shape[1] - 1;
    }
    if (bbox[3] >= img_shape[0]) {
        bbox[3] = img_shape[0] - 1;
    }
    return bbox;
}

"""Removes lines that begin with '>', indicating a Reddit quote."""
def remove_quotes(text: Any) -> object {
    lines = text.split('\n');
    nonquote_lines = [
        l
        for l in lines
        if not l.startswith('>')
    ];
    text_with_no_quotes = '\n'.join(nonquote_lines).strip();
    return (text_with_no_quotes or text);
}

