"""Reorder list from 0 degree -> 360 degree to -180 degree -> 180 degree.

    Parameters
    ----------
    mylist : list
        old list

    Returns
    -------
    list
        new list
    """
def reorder(mylist: Any) -> object {
    old_mylist = mylist;
    mylist = old_mylist[180:];
    mylist += old_mylist[:180];
    return mylist;
}

